public static void main(String[] args) {
    test("area of each shape", () -> {
        approx(area(new Circle(2)), Math.PI * 4, 1e-9);
        approx(area(new Rect(2, 3)), 6.0, 1e-9);
        approx(area(new Triangle(3, 4, 5)), 6.0, 1e-9);
    });
    test("perimeter of each shape", () -> {
        approx(perimeter(new Circle(1)), 2 * Math.PI, 1e-9);
        approx(perimeter(new Rect(2, 3)), 10.0, 1e-9);
        approx(perimeter(new Triangle(3, 4, 5)), 12.0, 1e-9);
    });
    test("records reject sizes that are not positive, NaN included", () -> {
        raises(IllegalArgumentException.class, () -> new Circle(0));
        raises(IllegalArgumentException.class, () -> new Circle(Double.NaN));
        raises(IllegalArgumentException.class, () -> new Rect(2, -1));
        raises(IllegalArgumentException.class, () -> new Triangle(0, 1, 1));
    });
    test("a Triangle's sides must close, strictly", () -> {
        raises(IllegalArgumentException.class, () -> new Triangle(1, 2, 3));
        raises(IllegalArgumentException.class, () -> new Triangle(1, 5, 1));
        approx(area(new Triangle(2, 2, 3)), Math.sqrt(3.5 * 1.5 * 1.5 * 0.5), 1e-9);
    });
    test("describe calls an equal-sided Rect a square", () -> {
        eq(describe(new Rect(3, 3)), "square 3.0");
        eq(describe(new Rect(2, 3)), "rect 2.0x3.0");
    });
    test("describe covers circles and triangles", () -> {
        eq(describe(new Circle(2)), "circle r=2.0");
        eq(describe(new Triangle(3, 4, 5)), "triangle 3.0/4.0/5.0");
    });
    test("permittedNames reads the sealed hierarchy at runtime", () ->
        eq(permittedNames(), List.of("Circle", "Rect", "Triangle")));
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("asInt passes Integers through and narrows Longs only when they fit", () -> {
        eq(asInt(42), Optional.of(42));
        eq(asInt(7L), Optional.of(7));
        eq(asInt((long) Integer.MIN_VALUE), Optional.of(Integer.MIN_VALUE));
        eq(asInt(3_000_000_000L), Optional.empty());
    });
    test("asInt accepts whole Doubles in range only", () -> {
        eq(asInt(3.0), Optional.of(3));
        eq(asInt(-0.0), Optional.of(0));
        eq(asInt(3.5), Optional.empty());
        eq(asInt(1e10), Optional.empty());
        eq(asInt(Double.NaN), Optional.empty());
    });
    test("asInt parses stripped digit strings and rejects the rest", () -> {
        eq(asInt(" 12 "), Optional.of(12));
        eq(asInt("-5"), Optional.of(-5));
        eq(asInt("12a"), Optional.empty());
        eq(asInt(""), Optional.empty());
        eq(asInt("99999999999"), Optional.empty());
        eq(asInt("+4"), Optional.empty());
    });
    test("asInt is empty for null, Booleans and other types", () -> {
        eq(asInt(null), Optional.empty());
        eq(asInt(true), Optional.empty());
        eq(asInt(List.of(1)), Optional.empty());
    });
    test("kind checks the blank case before the general text case", () -> {
        eq(kind("  "), "blank text");
        eq(kind(""), "blank text");
        eq(kind("hi"), "text");
        eq(kind(new StringBuilder("x")), "text");
    });
    test("kind names numbers, collections, maps and everything else", () -> {
        eq(kind(5), "integer");
        eq(kind(5L), "integer");
        eq(kind(2.5), "decimal");
        eq(kind(new BigDecimal("1.5")), "decimal");
        eq(kind(List.of(1, 2)), "collection of 2");
        eq(kind(Set.of()), "collection of 0");
        eq(kind(Map.of("a", 1)), "map of 1");
        eq(kind(null), "null");
        eq(kind(new Object()), "other: Object");
    });
    test("requireText returns stripped text and rejects anything else", () -> {
        eq(requireText("  ana ", "name"), "ana");
        var e = raises(IllegalArgumentException.class, () -> requireText(42, "name"));
        eq(e.getMessage(), "name must be text");
        raises(IllegalArgumentException.class, () -> requireText("   ", "city"));
        raises(IllegalArgumentException.class, () -> requireText(null, "city"));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("eval computes numbers, variables, sums, products and negation", () -> {
        var env = Map.of("x", 4L, "y", -2L);
        eq(eval(new Add(num(2), new Mul(v("x"), num(3))), env), 14);
        eq(eval(new Neg(new Mul(v("x"), v("y"))), env), 8);
    });
    test("eval of an unknown variable throws NoSuchElementException naming it", () -> {
        var e = raises(NoSuchElementException.class, () -> eval(new Add(v("x"), v("rate")), Map.of("x", 1L)));
        ok(e.getMessage().contains("rate"), "message: " + e.getMessage());
    });
    test("eval reports overflow as ArithmeticException", () -> {
        raises(ArithmeticException.class, () -> eval(new Mul(num(Long.MAX_VALUE), num(2)), Map.of()));
        raises(ArithmeticException.class, () -> eval(new Add(num(Long.MAX_VALUE), num(1)), Map.of()));
        raises(ArithmeticException.class, () -> eval(new Neg(num(Long.MIN_VALUE)), Map.of()));
    });
    test("show writes infix and brackets a sum inside a product", () -> {
        eq(show(new Add(num(1), new Mul(v("x"), num(2)))), "1 + x * 2");
        eq(show(new Mul(new Add(v("a"), num(1)), v("b"))), "(a + 1) * b");
        eq(show(new Mul(v("b"), new Add(v("a"), num(1)))), "b * (a + 1)");
        eq(show(new Add(new Add(v("a"), v("b")), v("c"))), "a + b + c");
        eq(show(new Add(v("a"), new Add(v("b"), v("c")))), "a + b + c");
        eq(show(new Mul(new Mul(v("a"), v("b")), new Neg(v("c")))), "a * b * -c");
    });
    test("show brackets a compound operand of Neg only", () -> {
        eq(show(new Neg(v("x"))), "-x");
        eq(show(new Neg(new Add(v("a"), num(1)))), "-(a + 1)");
        eq(show(new Neg(new Neg(v("x")))), "-(-x)");
        eq(show(new Add(v("a"), new Neg(v("b")))), "a + -b");
    });
    test("simplify folds constants and removes identity elements", () -> {
        eq(simplify(new Add(new Mul(v("x"), num(1)), num(0))), v("x"));
        eq(simplify(new Add(num(2), num(3))), num(5));
        eq(simplify(new Mul(num(0), v("y"))), num(0));
        eq(simplify(new Mul(v("a"), v("b"))), new Mul(v("a"), v("b")));
    });
    test("simplify works bottom-up, so one rewrite exposes the next", () -> {
        eq(simplify(new Add(v("x"), new Mul(num(2), num(0)))), v("x"));
        eq(simplify(new Mul(new Add(num(1), num(-1)), v("z"))), num(0));
        eq(simplify(new Neg(new Neg(v("x")))), v("x"));
        eq(simplify(new Neg(new Add(num(1), num(3)))), num(-4));
    });
    test("variables lists each name once, sorted", () -> {
        eq(variables(new Add(v("b"), new Mul(v("a"), new Neg(v("b"))))), List.of("a", "b"));
        eq(variables(num(3)), List.of());
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("map transforms an Ok and never calls f on an Err", () -> {
        var calls = new int[1];
        Function<Integer, Integer> times10 = x -> { calls[0]++; return x * 10; };
        eq(Result.ok(2).map(times10), new Ok<>(20));
        eq(Result.<Integer>err("boom").map(times10), new Err<>("boom"));
        eq(calls[0], 1);
    });
    test("flatMap chains steps that can fail", () -> {
        Function<Integer, Result<Integer>> atLeast5 = x -> x >= 5 ? Result.ok(x) : Result.err("too small: " + x);
        eq(Result.ok(10).flatMap(atLeast5), new Ok<>(10));
        eq(Result.ok(1).flatMap(atLeast5), new Err<>("too small: 1"));
        eq(Result.<Integer>err("earlier").flatMap(atLeast5), new Err<>("earlier"));
    });
    test("mapError rewrites only errors, and orElse unwraps with a fallback", () -> {
        eq(Result.<Integer>err("x").mapError(String::toUpperCase), new Err<>("X"));
        eq(Result.ok(3).mapError(String::toUpperCase), new Ok<>(3));
        eq(Result.ok(3).orElse(0), 3);
        eq(Result.<Integer>err("x").orElse(0), 0);
    });
    test("attempt turns an exception into an Err with its message or class name", () -> {
        eq(Result.attempt(() -> 5), new Ok<>(5));
        eq(Result.<Integer>attempt(() -> Integer.parseInt("x")), new Err<>("For input string: \"x\""));
        eq(Result.<Integer>attempt(() -> { throw new IllegalStateException(); }), new Err<>("IllegalStateException"));
    });
    test("sequence gives every value in order, or the first error", () -> {
        eq(Result.sequence(List.of(Result.ok(1), Result.ok(2))), new Ok<>(List.of(1, 2)));
        eq(Result.sequence(List.of(Result.ok(1), Result.<Integer>err("a"), Result.<Integer>err("b"))), new Err<>("a"));
        eq(Result.sequence(List.<Result<Integer>>of()), new Ok<>(List.of()));
    });
    test("parseLine accepts sku,qty with spaces around both parts", () -> {
        eq(parseLine(" AB-1 , 3 "), new Ok<>(new OrderLine("AB-1", 3)));
        eq(parseLine("Z,12"), new Ok<>(new OrderLine("Z", 12)));
    });
    test("parseLine names exactly what is wrong", () -> {
        eq(parseLine("AB-1"), new Err<>("expected sku,qty: AB-1"));
        eq(parseLine("a,b,c"), new Err<>("expected sku,qty: a,b,c"));
        eq(parseLine(" ,3"), new Err<>("missing sku"));
        eq(parseLine("AB,x"), new Err<>("bad quantity: x"));
        eq(parseLine("AB,"), new Err<>("bad quantity: "));
        eq(parseLine("AB,0"), new Err<>("quantity must be positive: 0"));
    });
    test("parseOrder reports the first bad line with its number", () -> {
        eq(parseOrder(List.of("A,1", "B,x", "C,0")), new Err<>("line 2: bad quantity: x"));
        eq(parseOrder(List.of("A,1", "B, 2")), new Ok<>(List.of(new OrderLine("A", 1), new OrderLine("B", 2))));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("PlainText joins the text and drops the formatting", () ->
        eq(ARTICLE.accept(new PlainText()), "Read the FAQ on refunds or ask us"));
    test("Markdown renders bold and links, nested", () -> {
        var doc = new Bold(List.of(new Text("hi "), new Link("u", List.of(new Text("there")))));
        eq(doc.accept(new Markdown()), "**hi [there](u)**");
        eq(new Link("/a", List.of()).accept(new Markdown()), "[](/a)");
    });
    test("Markdown escapes the characters it uses as syntax", () ->
        eq(new Text("2*3 [x]").accept(new Markdown()), "2\\*3 \\[x\\]"));
    test("LinkCollector lists urls in document order, outer before inner", () ->
        eq(ARTICLE.accept(new LinkCollector()), List.of("/faq", "/faq#refunds", "/contact")));
    test("NodeCounter is a new operation that needed no change to the nodes", () -> {
        eq(ARTICLE.accept(new NodeCounter()), 9);
        eq(new Text("x").accept(new NodeCounter()), 1);
    });
    test("depth is the deepest nesting, and an empty container counts as 1", () -> {
        eq(depth(ARTICLE), 4);
        eq(depth(new Text("x")), 1);
        eq(depth(new Bold(List.of())), 1);
    });
    test("mapText rewrites every Text and keeps the structure and urls", () -> {
        var doc = new Bold(List.of(new Text("a"), new Link("/x", List.of(new Text("b")))));
        eq(mapText(doc, s -> s.toUpperCase(Locale.ROOT)),
            new Bold(List.of(new Text("A"), new Link("/x", List.of(new Text("B"))))));
        eq(mapText(ARTICLE, s -> s).equals(ARTICLE), true);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("the happy path walks Draft to Shipped, carrying the data along", () ->
        eq(replay(List.of(new AddItem("a"), new AddItem("b"), new Place(), new Pay("p1"), new Ship("t9"))),
            new Shipped(List.of("a", "b"), "p1", "t9")));
    test("AddItem appends and leaves the old state unchanged", () -> {
        var before = new Draft(List.of("a"));
        eq(apply(before, new AddItem("b")), new Draft(List.of("a", "b")));
        eq(before, new Draft(List.of("a")));
    });
    test("an empty order cannot be placed", () -> {
        var e = raises(IllegalStateException.class, () -> apply(new Draft(List.of()), new Place()));
        eq(e.getMessage(), "cannot place an empty order");
    });
    test("cancelling before payment owes no refund; after payment it does", () -> {
        eq(apply(new Draft(List.of("a")), new Cancel("changed mind")), new Cancelled("changed mind", false));
        eq(apply(new Placed(List.of("a")), new Cancel("too slow")), new Cancelled("too slow", false));
        eq(apply(new Paid(List.of("a"), "p1"), new Cancel("duplicate")), new Cancelled("duplicate", true));
    });
    test("an illegal event names the event and the state", () -> {
        var e = raises(IllegalStateException.class, () -> apply(new Placed(List.of("a")), new Ship("t1")));
        eq(e.getMessage(), "cannot Ship when Placed");
        var late = raises(IllegalStateException.class, () -> apply(new Shipped(List.of("a"), "p", "t"), new Cancel("late")));
        eq(late.getMessage(), "cannot Cancel when Shipped");
    });
    test("items can only be added to a draft, and a cancelled order accepts nothing", () -> {
        var e = raises(IllegalStateException.class, () -> apply(new Placed(List.of("a")), new AddItem("b")));
        eq(e.getMessage(), "cannot AddItem when Placed");
        raises(IllegalStateException.class, () -> apply(new Cancelled("x", false), new AddItem("b")));
        raises(IllegalStateException.class, () -> apply(new Cancelled("x", false), new Cancel("again")));
    });
    test("replay stops at the first illegal event with its error", () -> {
        var e = raises(IllegalStateException.class, () -> replay(List.of(new AddItem("a"), new Pay("p"), new Place())));
        eq(e.getMessage(), "cannot Pay when Draft");
    });
    test("allowedEvents lists the legal next events per state, in event order", () -> {
        eq(allowedEvents(new Draft(List.of())), List.of("AddItem", "Place", "Cancel"));
        eq(allowedEvents(new Placed(List.of("a"))), List.of("Pay", "Cancel"));
        eq(allowedEvents(new Paid(List.of("a"), "p")), List.of("Ship", "Cancel"));
        eq(allowedEvents(new Shipped(List.of("a"), "p", "t")), List.of());
        eq(allowedEvents(new Cancelled("x", true)), List.of());
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("render writes null, booleans, and whole or fractional numbers", () -> {
        eq(render(NULL), "null");
        eq(render(new JBool(true)), "true");
        eq(render(num(3.0)), "3");
        eq(render(num(-0.0)), "0");
        eq(render(num(-2.5)), "-2.5");
        eq(render(num(1e20)), "1.0E20");
    });
    test("JNum rejects NaN and the infinities", () -> {
        raises(IllegalArgumentException.class, () -> num(Double.NaN));
        raises(IllegalArgumentException.class, () -> num(Double.POSITIVE_INFINITY));
        eq(num(0.5).value(), 0.5);
    });
    test("render escapes quotes, backslashes and control characters", () -> {
        eq(render(str("a\"b\\c\nd\te\u0001")), "\"a\\\"b\\\\c\\nd\\te\\u0001\"");
        eq(render(str("\r\u001f")), "\"\\u000d\\u001f\"");
        var accented = "caf" + (char) 0xE9;
        eq(render(str(accented)), "\"" + accented + "\"");
    });
    test("render keeps object fields in insertion order and nests arrays", () -> {
        var order = obj("id", num(7), "tags", arr(str("a"), str("b")), "ok", new JBool(false), "note", NULL);
        eq(render(order), "{\"id\":7,\"tags\":[\"a\",\"b\"],\"ok\":false,\"note\":null}");
        eq(render(obj("empty", arr(), "nested", obj())), "{\"empty\":[],\"nested\":{}}");
    });
    test("at follows a dot path through fields and array indexes", () -> {
        var doc = obj("customer", obj("name", str("Ana")), "orders", arr(obj("sku", str("A1")), obj("sku", str("B2"))));
        eq(at(doc, "orders.1.sku"), Optional.of(str("B2")));
        eq(at(doc, "customer.name"), Optional.of(str("Ana")));
        eq(at(doc, ""), Optional.of(doc));
    });
    test("at is empty for a missing field, a bad index or the wrong container", () -> {
        var doc = obj("customer", obj("name", str("Ana")), "orders", arr(obj("sku", str("A1"))));
        eq(at(doc, "orders.5"), Optional.empty());
        eq(at(doc, "orders.x"), Optional.empty());
        eq(at(doc, "orders.-1"), Optional.empty());
        eq(at(doc, "customer.0"), Optional.empty());
        eq(at(doc, "nope.deeper"), Optional.empty());
        eq(at(doc, "customer.name.first"), Optional.empty());
    });
    test("merge replaces, adds, and removes fields patched with null", () -> {
        var merged = merge(obj("a", num(1), "b", num(2)), obj("b", num(3), "a", NULL, "c", num(4)));
        eq(render(merged), "{\"b\":3,\"c\":4}");
        eq(merge(obj("a", num(1)), str("x")), str("x"));
    });
    test("merge recurses into objects and replaces anything else whole", () -> {
        var base = obj("user", obj("name", str("Ana"), "city", str("Oslo")), "tags", arr(str("x")));
        var patch = obj("user", obj("city", str("Lima")), "tags", arr(str("y"), str("z")));
        eq(render(merge(base, patch)), "{\"user\":{\"name\":\"Ana\",\"city\":\"Lima\"},\"tags\":[\"y\",\"z\"]}");
        eq(render(merge(num(1), obj("a", NULL, "b", obj("c", NULL)))), "{\"b\":{}}");
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("leaves lists every concrete payment type, through nested sealed types", () -> {
        eq(leaves(Payment.class), List.of("ApplePay", "BankTransfer", "Card", "PayPal"));
        eq(leaves(Wallet.class), List.of("ApplePay", "PayPal"));
    });
    test("a dispatcher with a handler per leaf routes each value", () -> {
        var fee = Dispatcher.<Payment, String>forSealed(Payment.class)
            .on(Card.class, c -> "card " + c.last4())
            .on(BankTransfer.class, b -> "bank")
            .on(ApplePay.class, a -> "apple " + a.device())
            .on(PayPal.class, p -> "paypal")
            .build();
        eq(SAMPLES.stream().map(fee::dispatch).toList(), List.of("card 4242", "bank", "apple watch", "paypal"));
    });
    test("a handler for a sealed sub-interface covers all its leaves", () -> {
        var kind = Dispatcher.<Payment, String>forSealed(Payment.class)
            .on(Card.class, c -> "card")
            .on(BankTransfer.class, b -> "bank")
            .on(Wallet.class, w -> "wallet")
            .build();
        eq(SAMPLES.stream().map(kind::dispatch).toList(), List.of("card", "bank", "wallet", "wallet"));
    });
    test("a leaf's own handler beats its sealed parent's", () -> {
        var kind = Dispatcher.<Payment, String>forSealed(Payment.class)
            .on(Card.class, c -> "card")
            .on(BankTransfer.class, b -> "bank")
            .on(Wallet.class, w -> "wallet")
            .on(PayPal.class, p -> "paypal")
            .build();
        eq(kind.dispatch(new PayPal("x")), "paypal");
        eq(kind.dispatch(new ApplePay("x")), "wallet");
    });
    test("a root handler is a fallback that specific handlers override", () -> {
        var risk = Dispatcher.<Payment, Integer>forSealed(Payment.class)
            .on(Payment.class, p -> 1)
            .on(Card.class, c -> 5)
            .build();
        eq(SAMPLES.stream().map(risk::dispatch).toList(), List.of(5, 1, 1, 1));
        var tiered = Dispatcher.<Payment, Integer>forSealed(Payment.class)
            .on(Payment.class, p -> 1)
            .on(Wallet.class, w -> 2)
            .on(Card.class, c -> 5)
            .build();
        eq(SAMPLES.stream().map(tiered::dispatch).toList(), List.of(5, 1, 2, 2));
    });
    test("build refuses missing cases and names them, sorted", () -> {
        var builder = Dispatcher.<Payment, String>forSealed(Payment.class).on(Card.class, c -> "card");
        var e = raises(IllegalStateException.class, builder::build);
        eq(e.getMessage(), "unhandled: ApplePay, BankTransfer, PayPal");
    });
    test("registering one type twice is an error", () -> {
        var builder = Dispatcher.<Payment, String>forSealed(Payment.class).on(Card.class, c -> "a");
        raises(IllegalStateException.class, () -> builder.on(Card.class, c -> "b"));
    });
    test("forSealed refuses a type that is not sealed", () -> {
        raises(IllegalArgumentException.class, () -> Dispatcher.<Card, String>forSealed(Card.class));
        raises(IllegalArgumentException.class, () -> Dispatcher.<String, String>forSealed(String.class));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

